from .pm_error import PmError
from .pm_config import PmConfig

from mazegenerator import MazeGenerator
import pygame
from pygame.locals import (
    K_UP,
    K_DOWN,
    K_LEFT,
    K_RIGHT,
    K_ESCAPE,
    KEYDOWN,
    QUIT,
)

# • A maze with walls and corridors, generated by the assigned A-Maze-ing package.
# • The first level is composed of a maze generated with a fixed seed (e.g., 42), then, each
# subsequent level is composed of a maze randomly generated.
# • Pacgums (small dots) in most corridors.
# • Super-pacgums (power pellets) in the 4 corners of the maze.
# • 4 ghosts, one in each corner of the maze.
# • The player starts in the middle of the maze


# class Level:
#     def __init__(self):
#         pass


N, E, S, W = 1, 2, 4, 8
Margin = 40
WallColor = (60, 90, 200)


class Maze():

    grid: list[list[int]] = []

    def __init__(self) -> None:
        try:
            gen = MazeGenerator(size=(PmConfig.width, PmConfig.height), perfect=False, seed=PmConfig.seed)
            Maze.grid = gen.maze
        except Exception as e:
            PmError("[error]No configuration file provide. "
                    f"Failed to load maze: {e}")

    @classmethod
    def draw_line(cls, screen: pygame.Surface, start: tuple[int, int], end: tuple[int, int], color: tuple[int, int, int], width: int = 1) -> None:
        pygame.draw.line(screen, color, start, end, width)

    @classmethod
    def draw_rectangle(cls, screen: pygame.Surface, rect: pygame.Rect, color: tuple[int, int, int], width: int = 0) -> None:
        pygame.draw.rect(screen, color, rect, width)

    @classmethod
    def draw_maze(cls, screen: pygame.Surface, grid: list[list[int]], cell_size: int = 48) -> None:
        for y, row in enumerate(grid):
            for x, cell in enumerate(row):
                px = x * cell_size
                py = y * cell_size
                if cell == 15:  
                    cls.draw_rectangle(screen, pygame.Rect(px, py, cell_size, cell_size), (0, 0, 255))
                if cell & N:  
                    cls.draw_line(screen, (px, py), (px + cell_size, py), WallColor, 2)
                if cell & E:  
                    cls.draw_line(screen, (px + cell_size, py), (px + cell_size, py + cell_size), WallColor, 2)
                if cell & S:  
                    cls.draw_line(screen, (px, py + cell_size), (px + cell_size, py + cell_size), WallColor, 2)
                if cell & W:  
                    cls.draw_line(screen, (px, py), (px, py + cell_size), WallColor, 2)

    @classmethod
    def display_maze(cls) -> None:
        pygame.init()
        pygame.display.set_caption("Pac-Man")
        screen = pygame.display.set_mode((PmConfig.width * 48, PmConfig.height * 48))

        screen.fill((0, 0, 0))
        cls.draw_maze(screen, Maze.grid)
        pygame.display.flip()

